package com.assetflow.service;
import org.springframework.beans.factory.annotation.Value;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;
@Service public class AgentAuth{private final JdbcTemplate db;private final String registration;public AgentAuth(JdbcTemplate db,@Value("${assetflow.registration-token}")String registration){this.db=db;this.registration=registration;}public boolean registrationValid(String value){return secretValid(registration,value);}public boolean secretValid(String expected,String value){return value!=null&&MessageDigest.isEqual(expected.getBytes(StandardCharsets.UTF_8),value.getBytes(StandardCharsets.UTF_8));}public UUID authenticate(String value){if(value==null||!value.startsWith("Bearer "))return null;var ids=db.query("SELECT id FROM agent WHERE token_hash=?",(r,n)->r.getObject(1,UUID.class),hash(value.substring(7)));return ids.isEmpty()?null:ids.getFirst();}public static String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}}
